<script setup>
import {ref,onMounted} from 'vue';import AppShell from '../components/AppShell.vue';import {supabase} from '../services/supabase';const form=ref({full_name:'',company_name:'',business_registration:'',location:'',bio:'',phone:'',course:'',year_of_study:'',skills:[]}),skillText=ref(''),email=ref(''),message=ref(''),error=ref(''),busy=ref(false);onMounted(async()=>{const {data:{user}}=await supabase.auth.getUser();email.value=user?.email||'';const {data}=await supabase.from('profiles').select('*').eq('id',user.id).maybeSingle();if(data)form.value={...form.value,...data,skills:data.skills||[]}});function addSkill(){const s=skillText.value.trim();if(s&&!form.value.skills.includes(s))form.value.skills.push(s);skillText.value=''}async function save(){busy.value=true;message.value='';error.value='';const {data:{user}}=await supabase.auth.getUser();const {error:e}=await supabase.from('profiles').update({...form.value,updated_at:new Date().toISOString()}).eq('id',user.id);if(e)error.value=e.message;else message.value='Your profile has been updated.';busy.value=false}
</script>
<template><AppShell title="My profile" subtitle="Tell employers a little about yourself"><template #default><div class="profile-page"><span class="eyebrow">YOUR CAMPUS GIG IDENTITY</span><h1 class="page-title">Your profile</h1><p class="page-subtitle">A complete profile helps employers understand what you bring.</p><form class="card" style="margin-top:22px" @submit.prevent="save"><div v-if="message" class="alert success">{{message}}</div><div v-if="error" class="alert error">{{error}}</div><div class="grid grid-2"><div class="field"><label>Full name</label><input v-model="form.full_name" class="input" required></div><div class="field"><label>Email address</label><input :value="email" class="input" disabled></div><div class="field"><label>Business / organisation</label><input v-model="form.company_name" class="input" placeholder="For employer accounts"></div><div class="field"><label>Business registration number</label><input v-model="form.business_registration" class="input" placeholder="For employer accounts"></div><div class="field"><label>Location</label><input v-model="form.location" class="input" placeholder="e.g. Khayelitsha, Cape Town"></div><div class="field"><label>Phone number</label><input v-model="form.phone" class="input" placeholder="Optional contact number"></div><div class="field"><label>Course / qualification</label><input v-model="form.course" class="input" placeholder="e.g. Diploma in ICT"></div><div class="field"><label>Year of study</label><select v-model="form.year_of_study" class="input"><option value="">Select year</option><option>1st year</option><option>2nd year</option><option>3rd year</option><option>4th year</option><option>Graduate</option><option>Not applicable</option></select></div></div><div class="field"><label>About you</label><textarea v-model="form.bio" class="input" placeholder="Introduce yourself, your experience and what kind of work you're looking for…"></textarea></div><div class="field"><label>Skills</label><div class="skill-entry"><input v-model="skillText" class="input" placeholder="Add a skill e.g. Customer service" @keyup.enter.prevent="addSkill"><button type="button" class="btn btn-outline" @click="addSkill">Add</button></div><div class="skills"><button v-for="s in form.skills" :key="s" type="button" class="badge" @click="form.skills=form.skills.filter(x=>x!==s)">{{s}} ×</button></div></div><button class="btn btn-primary" :disabled="busy">{{busy?'Saving…':'Save profile'}}</button></form></div></template></AppShell></template>
<style scoped>.profile-page{max-width:850px;margin:auto}.skill-entry{display:flex;gap:9px}.skills{display:flex;gap:7px;flex-wrap:wrap;margin-top:10px}.skills button{border:0;cursor:pointer}</style>
